<div class="page-header d-flex"><h2><?= lang('users') ?></h2><a class="btn btn-primary ms-auto" href="<?= site_url('users/create') ?>"><?= lang('add_user') ?></a></div><div class="card"><table class="table data-table" data-source="<?= site_url('users/data') ?>" data-fields="name,email,role,warehouse,status,action"><thead><tr><th><?= lang('name') ?></th><th><?= lang('email') ?></th><th><?= lang('role') ?></th><th><?= lang('warehouse') ?></th><th><?= lang('status') ?></th><th></th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e($user['name']) ?></td><td><?= e($user['email']) ?></td><td><?= e(lang($user['role']==='admin'?'admin':'warehouse_user')) ?></td><td><?= e($user['warehouse']) ?></td><td><?= e(lang($user['status'])) ?></td><td><a class="btn btn-sm" href="<?= site_url('users/edit/'.$user['id']) ?>"><?= lang('edit') ?></a></td></tr><?php endforeach; ?></tbody></table></div>
